func gwParseQuery():
	var out = {}
	if not OS.has_feature("JavaScript"):
		return out
	var s = JavaScript.eval("window.location.search")
	if typeof(s) != TYPE_STRING:
		return out
	if s.begins_with("?"):
		s = s.substr(1)
	for part in s.split("&"):
		var kv = part.split("=")
		if kv.size() == 2:
			out[kv[0]] = kv[1]
	return out

func gwQuickStart():
	var titles = get_tree().get_nodes_in_group("title")
	if titles.size() == 0 or game == null or not is_instance_valid(game):
		gwTries += 1
		if gwTries < 200:
			call_deferred("gwQuickStart")
		return
	titles[0].queue_free()
	launchChooseChar()
	game.launchGame(1)
	self.difficulty = gwQuickDifficulty
	for cc in get_tree().get_nodes_in_group("chooseChar"):
		cc.queue_free()
	for player in get_tree().get_nodes_in_group("player"):
		if player.number == 1:
			player.character = gwQuickChar
	myConst.on_menu = false
	game.mapLevel = gwQuickWorld
	myConst._updateChunck()
	game.launchMap()
	gwQuickPending = false

func gwOnLevelStarted():
	gwBossY = null
	gwBossLifeMax = 0.0
	gwBossSeen = false
	var cams = get_tree().get_nodes_in_group("cam")
	if cams.size():
		gwCamStartY = cams[0].get_global_position().y

func gwScreen():
	if game == null or not is_instance_valid(game):
		return gwPhase
	if get_tree().get_nodes_in_group("gameOver").size():
		return "game_over"
	if get_tree().get_nodes_in_group("endGame").size() or get_tree().get_nodes_in_group("endCinematic").size():
		return "ending"
	if get_tree().get_nodes_in_group("title").size():
		return "title"
	if get_tree().get_nodes_in_group("chooseChar").size():
		return "character_select"
	if get_tree().get_nodes_in_group("tuto").size() or get_tree().get_nodes_in_group("tutoCtrl").size():
		return "tutorial"
	if get_tree().get_nodes_in_group("shopMenu").size():
		return "shop"
	if get_tree().get_nodes_in_group("endLevel").size():
		return "stage_clear"
	var pz = get_tree().get_nodes_in_group("pause")
	if get_tree().paused and pz.size() and pz[0].visible:
		return "paused"
	if get_tree().get_nodes_in_group("introLevel").size():
		return "stage_intro"
	if not get_tree().get_nodes_in_group("playerDeath").size():
		return "loading"
	return "playing"

func gwPublish():
	if not OS.has_feature("JavaScript"):
		return
	var snap = {"screen": gwScreen(), "quick_pending": gwQuickPending, "quick": gwQuick}
	if game != null and is_instance_valid(game):
		if game != gwGame:
			gwGame = game
			game.connect("level_started", self, "gwOnLevelStarted")
		var players = []
		var kills = 0
		for p in get_tree().get_nodes_in_group("playerDeath"):
			if p.is_queued_for_deletion():
				continue
			var life = p.life if p.life != null else 0
			players.append({"number": p.number, "life": life, "sphere_max": p.sphereMax, 
				"score": p.score, "deaths": p.deathCount, "character": p.character, 
				"dead": bool(p.death), "shield": p.shield, "item_levels": p.itemLevel, 
				"shots": p.nbrPrecisionShoot, "hits": p.nbrPrecisionTouch})
			kills += p.score
		snap["players"] = players
		snap["enemies_destroyed"] = kills

		var hb = get_tree().get_nodes_in_group("hudBar")
		if hb.size() and hb[0].visible:
			var lbl = hb[0].get_node("level")
			var want = "STAGE: " + str(game.mapLevel) + "  KILLS: " + str(kills)
			if lbl.text != want:
				lbl.set_text(want)
		snap["world"] = game.mapLevel
		snap["credit"] = game.credit
		snap["run_time_s"] = game.gameTime
		snap["upgrades_bought"] = game.upgradesBought
		snap["worlds_cleared_list"] = game.cleared.keys()
		snap["paused"] = get_tree().paused

		var cams = get_tree().get_nodes_in_group("cam")
		var camY = gwCamStartY
		if cams.size():
			camY = cams[0].get_global_position().y
		var bossLife = 0.0
		var bossNodes = 0
		for e in get_tree().get_nodes_in_group("enemy"):
			if e.boss and not e.bossPart and not e.is_queued_for_deletion():
				bossNodes += 1
				bossLife += max(e.life, 0.0)
				if gwBossY == null:
					gwBossY = e.get_global_position().y + 40
		if bossNodes:
			gwBossSeen = true
			gwBossLifeMax = max(gwBossLifeMax, bossLife)
		var dmg = 0.0
		if gwBossSeen and gwBossLifeMax > 0:
			dmg = 1.0 - clamp(bossLife / gwBossLifeMax, 0.0, 1.0)
		var pos = 0.0
		if gwBossY != null and gwCamStartY - gwBossY > 1:
			pos = clamp((gwCamStartY - camY) / (gwCamStartY - gwBossY), 0.0, 1.0)
		snap["scroll_fraction"] = pos
		snap["boss_damage_fraction"] = dmg
		snap["boss_present"] = bossNodes > 0
		snap["boss_life"] = bossLife
	snap["difficulty"] = difficulty
	snap["obs"] = gwObservation()
	JavaScript.eval("window.gwSnapshot && window.gwSnapshot(" + to_json(snap) + ")")







var gwPrev = {}
var gwSeen = {}
const GW_SCALE = 1.25
const GW_MAX = 64
const GW_FIELD_L = 170.0
const GW_FIELD_R = 470.0

func gwR(v, step = 0.1):
	return stepify(v, step)

func gwFindShape(node):
	for c in node.get_children():
		if (c is CollisionShape2D or c is CollisionPolygon2D) and not c.disabled:
			return c
	return null

func gwShapeBox(n):
	if n == null:
		return null
	var pts = []
	if n is CollisionShape2D:
		var s = n.shape
		var ex = Vector2(0, 0)
		if s is RectangleShape2D:
			ex = s.extents
		elif s is CircleShape2D:
			ex = Vector2(s.radius, s.radius)
		elif s is CapsuleShape2D:
			ex = Vector2(s.radius, s.radius + s.height / 2.0)
		else:
			return null
		pts = [Vector2( - ex.x, - ex.y), Vector2(ex.x, - ex.y), Vector2(ex.x, ex.y), Vector2( - ex.x, ex.y)]
	elif n is CollisionPolygon2D:
		pts = Array(n.polygon)
	if pts.size() == 0:
		return null
	var xf = game_node.get_canvas_transform() * n.get_global_transform()
	var mn = Vector2(INF, INF)
	var mx = Vector2( - INF, - INF)
	var mean = Vector2(0, 0)
	var spts = []
	for p in pts:
		var q = xf.xform(p)
		spts.append([gwR(q.x * GW_SCALE, 1.0), gwR(q.y * GW_SCALE, 1.0)])
		mn.x = min(mn.x, q.x)
		mn.y = min(mn.y, q.y)
		mx.x = max(mx.x, q.x)
		mx.y = max(mx.y, q.y)
		mean += q
	var c = (mn + mx) / 2.0
	if n is CollisionPolygon2D:
		c = mean / pts.size()
	return {"c": c * GW_SCALE, "h": (mx - mn) / 2.0 * GW_SCALE, "poly": spts if n is CollisionPolygon2D else null}

func gwOnScreen(c, margin):
	return c.x > GW_FIELD_L - margin and c.x < GW_FIELD_R + margin and c.y > - margin and c.y < 360 + margin

func gwEntity(node, shape, extra, margin = 24):
	var b = gwShapeBox(shape)
	if b == null:
		return null
	var c = b["c"]
	var h = b["h"]
	if c.x + h.x < GW_FIELD_L - margin or c.x - h.x > GW_FIELD_R + margin or c.y + h.y < - margin or c.y - h.y > 360 + margin:
		return null
	var id = node.get_instance_id()
	var ms = OS.get_ticks_msec()
	var vx = 0.0
	var vy = 0.0
	if gwPrev.has(id):
		var pv = gwPrev[id]
		var dt = (ms - pv[2]) / 1000.0
		if dt > 0.0 and dt <= 0.25:
			vx = (c.x - pv[0]) / dt
			vy = (c.y - pv[1]) / dt
	gwSeen[id] = [c.x, c.y, ms]
	var d = {"id": id, "x": gwR(c.x), "y": gwR(c.y), "vx": gwR(vx, 0.01), "vy": gwR(vy, 0.01), 
		"hw": gwR(h.x), "hh": gwR(h.y), "r": gwR((h.x + h.y) / 2.0)}
	if b["poly"] != null and b["poly"].size() <= 24:
		d["poly"] = b["poly"]
	for k in extra.keys():
		d[k] = extra[k]
	return d

func gwPlayerEntry():
	for p in get_tree().get_nodes_in_group("playerDeath"):
		if p.is_queued_for_deletion() or not p.has_node("shape"):
			continue
		if p.number != 1:
			continue
		return gwEntity(p, p.get_node("shape"), {"dead": bool(p.death), 
			"invincible": p.get_node("invincibleTime").time_left > 0}, 1000)
	return null

func gwEnemyEntries():
	var out = []
	var seen = {}
	for e in get_tree().get_nodes_in_group("enemy"):
		if out.size() >= GW_MAX:
			break
		if e.is_queued_for_deletion() or not e.is_visible_in_tree() or e.death or not e.has_node("shape"):
			continue
		var extra = {"kind": "enemy", "name": str(e.name), "boss": bool(e.boss), "boss_part": bool(e.bossPart), 
			"damageable": bool(e.active) and e.life > 0 and not e.get_node("justCreate").time_left, 
			"solid": bool(e.solid)}
		var d = gwEntity(e, e.get_node("shape"), extra)
		if d == null:
			continue
		if e.has_node("playerHitArea"):
			var cb = gwShapeBox(gwFindShape(e.get_node("playerHitArea")))
			if cb != null:
				d["contact"] = {"x": gwR(cb["c"].x), "y": gwR(cb["c"].y), "hw": gwR(cb["h"].x), "hh": gwR(cb["h"].y)}
		seen[e.get_instance_id()] = true
		out.append(d)
	for group in ["destructible", "wall"]:
		for w in get_tree().get_nodes_in_group(group):
			if out.size() >= GW_MAX:
				break
			if seen.has(w.get_instance_id()) or w.is_queued_for_deletion() or not w.is_visible_in_tree():
				continue
			var destructible = w.is_in_group("destructible")
			if destructible and w.life <= 0:
				continue
			var d = gwEntity(w, gwFindShape(w), {"kind": "destructible" if destructible else "wall", 
				"name": str(w.name), "boss": false, "boss_part": false, "damageable": destructible, "solid": true})
			if d != null:
				seen[w.get_instance_id()] = true
				out.append(d)
	return out

func gwProjectileEntries():
	var out = []
	for s in get_tree().get_nodes_in_group("shoot"):
		if out.size() >= GW_MAX:
			break
		if s.team != "enemy" or s.is_queued_for_deletion() or not s.is_visible_in_tree() or not s.has_node("pos/area"):
			continue
		var d = gwEntity(s, gwFindShape(s.get_node("pos/area")), {"kind": "shot", "damage": s.damage})
		if d != null:
			out.append(d)
	for e in get_tree().get_nodes_in_group("enemy"):
		if e.is_queued_for_deletion() or not e.is_visible_in_tree() or e.death:
			continue
		for c in e.get_children():
			if c.has_node("laserReload") and c.has_node("laser") and c.has_node("area") and c.get_node("laser").visible and c.get_node("area").monitoring:
				var d = gwEntity(c, gwFindShape(c.get_node("area")), {"kind": "laser", "damage": 1})
				if d != null:
					out.append(d)
	return out

func gwPickupEntries():
	var out = []
	for s in get_tree().get_nodes_in_group("sphere"):
		if out.size() >= GW_MAX:
			break
		if s.is_queued_for_deletion() or not s.is_visible_in_tree() or not s.has_node("area"):
			continue
		var d = gwEntity(s, gwFindShape(s.get_node("area")), {"kind": "mega_sphere" if s.megaSphere else "sphere", 
			"collectable": not s.get_node("justCreate").time_left})
		if d != null:
			out.append(d)
	for s in get_tree().get_nodes_in_group("inGameItem"):
		if out.size() >= GW_MAX:
			break
		if s.is_queued_for_deletion() or not s.is_visible_in_tree() or not s.has_node("area"):
			continue
		var d = gwEntity(s, gwFindShape(s.get_node("area")), {"kind": "special_item", 
			"collectable": not s.get_node("justCreate").time_left})
		if d != null:
			out.append(d)
	return out

func gwShopUi():
	var menus = get_tree().get_nodes_in_group("shopMenu")
	if menus.size() == 0 or not menus[0].has_node("buyPanel"):
		return null
	var m = menus[0]
	var bp = m.get_node("buyPanel")
	var sel = bp.itemSelect
	var life = 0
	if bp.myPlayer != null and is_instance_valid(bp.myPlayer):
		life = bp.myPlayer.life
	var items = []
	for child in bp.get_node("itemCtnr").get_children():
		if child.item == null:
			continue
		var info = myConst.ITEM_LIST[child.item - 1]
		var price = null
		var afford = false
		if not child.outOfStock:
			price = myConst.getPrice(ceil(info.get("price") / game.priceSale), child.level)
			afford = price <= life
		items.append({"index": int(str(child.name)) - 1, "effect": info.get("effect"), "level": child.level, 
			"price": price, "affordable": afford, "sold": bool(child.outOfStock)})
	return {"cursor": int(sel.x) + 2 * int(sel.y), "spheres": life, "items": items, 
		"purchase_popup": {"open": bool(bp.buyMenu), "selection": "yes" if bp.yes else "no"}, 
		"leave_popup": {"open": bool(m.askForQuit), "selection": "yes" if m.yes else "no"}}

func gwLabDoor():
	var door = null
	for s in get_tree().get_nodes_in_group("shop"):
		if s.is_queued_for_deletion() or not s.is_visible_in_tree() or not s.has_node("area"):
			continue
		var b = gwShapeBox(gwFindShape(s.get_node("area")))
		if b != null and gwOnScreen(b["c"], 0):
			door = {"x": gwR(b["c"].x), "y": gwR(b["c"].y), "hw": gwR(b["h"].x), "hh": gwR(b["h"].y), 
				"enterable": bool(s.ready)}
			break
	return {"door": door, "shop": gwShopUi()}

func gwObservation():
	if game == null or not is_instance_valid(game) or not get_tree().get_nodes_in_group("playerDeath").size():
		gwPrev = {}
		return null
	gwSeen = {}
	var obs = {"player": gwPlayerEntry(), "enemies": gwEnemyEntries(), "enemy_projectiles": gwProjectileEntries(), 
		"pickups": gwPickupEntries(), "lab_door": gwLabDoor()}
	gwPrev = gwSeen
	return obs
